import {demoProject,factorySamples,makeTrack,makeClip,History,uid,clone,clamp,noteName,COLORS,validateProject} from './engine/model.js';
import {AudioHost} from './engine/audio.js';
import {Surface,WaveCache} from './engine/visual.js';
import {autosave,restore,serialize,deserialize,download} from './engine/storage.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],icon=name=>`<svg><use href="#i-${name}"/></svg>`,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const audio=new AudioHost(),waves=new WaveCache(),liveRoutes=new Map();
const ui={track:0,scene:0,detail:'clip',base:36,grid:.25,velocity:100/127,draw:false,selectedNote:null,selectedInstance:null,bars:16,automation:false,record:null,recordHeld:new Map(),held:new Map(),octave:0,category:'Sounds',dirty:true,exportWorker:null,gesture:null};
let toastTimer,saveTimer,saveChain=Promise.resolve(),dragDepth=0,metronome=false,taps=[];
const history=new History(demoProject(),(project,label)=>{audio.setProject(project);renderAll();scheduleSave();$('#status-message').textContent=label;});
const project=()=>history.project,track=()=>project().tracks[ui.track],clip=()=>track()?.clips[ui.scene];
function message(text,error=false){$('#toast').textContent=text;$('#toast').classList.toggle('error',error);$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),error?6500:3300);$('#status-message').textContent=text;}
async function safe(fn){try{return await fn();}catch(e){console.error(e);message(e.message||String(e),true);}}
function commit(label,fn){history.commit(label,fn);}
function scheduleSave(){clearTimeout(saveTimer);$('#save-status').textContent='Unsaved changes';saveTimer=setTimeout(()=>{const snapshot=clone(project());saveChain=saveChain.catch(()=>{}).then(()=>autosave(snapshot,audio.assets)).then(()=>$('#save-status').textContent='Saved locally').catch(()=>$('#save-status').textContent='Storage unavailable · save a file');},700);}
function updateTitles(){$('#project-title').textContent=project().name;$('#set-name').textContent=project().name;document.title=`Pulsegrid — ${project().name}`;$('#tempo').value=project().bpm;$('#quantum').value=project().quantum;$('#loop').classList.toggle('active',project().loop);$('#loop').setAttribute('aria-pressed',project().loop);$('#undo').disabled=!history.past.length;}
function preview(c,t){if(c.kind==='audio'){const a=audio.assets.get(c.sampleId);if(!a)return '';const bars=[];for(let i=0;i<28;i++){let peak=0;const at=Math.floor(i/28*a.frames);for(let j=at;j<Math.min(a.frames,at+256);j++)peak=Math.max(peak,Math.abs(a.channels[0][j]));bars.push(`<i style="height:${Math.max(1,peak*45)}px"></i>`);}return `<div class="clip-audio-line">${bars.join('')}</div>`;}
  if(!c.notes.length)return '';const min=Math.min(...c.notes.map(n=>n.pitch)),max=Math.max(...c.notes.map(n=>n.pitch));return c.notes.slice(0,80).map(n=>`<i class="clip-note" style="left:${n.start/c.length*100}%;width:${Math.min(n.duration,c.length-n.start)/c.length*100}%;top:${(1-(n.pitch-min)/(Math.max(1,max-min)))*75}%"></i>`).join('');}
function renderTracks(){const p=project();$('#track-grid').innerHTML=p.tracks.map((t,i)=>`<article class="track" style="--track-color:${t.color}" data-track="${i}"><header class="track-header ${i===ui.track?'selected':''}" data-select-track="${i}" title="Select track · double-click to rename"><span class="track-number">${i+1}</span><strong>${esc(t.name)}</strong>${icon(t.type==='audio'?'wave':t.instrument==='drums'?'drum':'key')}</header><div class="clip-slots">${p.scenes.map((_,s)=>{const c=t.clips[s];return `<div class="clip-slot ${c?'':'empty'}" data-track="${i}" data-scene="${s}">${c?`<div class="clip ${i===ui.track&&s===ui.scene?'selected':''}" data-track="${i}" data-scene="${s}" draggable="true"><div class="clip-top"><button class="clip-launch" data-launch="${i}:${s}" title="Launch ${esc(c.name)}">${icon('play')}</button><span class="clip-name">${esc(c.name)}</span></div><div class="clip-preview">${preview(c,t)}</div><i class="clip-progress hidden"></i></div>`:`<button class="empty-slot-button" data-create="${i}:${s}" title="Create an empty ${t.type==='audio'?'audio':'MIDI'} clip">+</button>`}</div>`;}).join('')}</div><div class="track-stop"><button data-stop-track="${i}" title="Stop this track at the next launch boundary">■</button><span>${t.type==='audio'?'AUDIO':'MIDI'} → MAIN</span></div><div class="track-mixer"><div class="routing"><span>${t.type==='audio'?(t.monitor?'Input monitor':'Audio / samples'):t.instrument==='drums'?'Drum machine':t.instrument==='sampler'?'Sampler':'Internal synth'}</span><span>⌄</span></div><div class="pan-row"><span>L</span><input data-mix="pan" data-track="${i}" aria-label="${esc(t.name)} pan" type="range" min="-1" max="1" step="0.01" value="${t.pan}"><span>R</span></div><div class="mixer-center"><div class="meter-scale"><span>0</span><span>−12</span><span>−∞</span></div><input class="volume-control" data-mix="volume" data-track="${i}" aria-label="${esc(t.name)} volume" type="range" min="0" max="1.2" step="0.005" value="${t.volume}"><div class="meter-pair"><div class="meter-well"><i class="meter-fill" id="meter-${i}-l"></i></div><div class="meter-well"><i class="meter-fill" id="meter-${i}-r"></i></div></div></div><div class="volume-label" id="volume-${i}">${db(t.volume)}</div><div class="track-buttons"><button class="track-activate ${t.mute?'muted':''}" data-toggle="mute" data-track="${i}" title="Track activator (mute)">${i+1}</button><button class="solo ${t.solo?'on':''}" data-toggle="solo" data-track="${i}" title="Solo">S</button><button class="arm ${t.arm?'on':''}" data-toggle="arm" data-track="${i}" title="Arm track for recording">●</button></div></div></article>`).join('');
  $('#scene-column').innerHTML=`<header class="master-header">Master <span>◁</span></header>${p.scenes.map((name,s)=>`<button class="scene-launch ${s===ui.scene?'selected':''}" data-scene-launch="${s}" title="Launch scene ${s+1}: ${esc(name)}">${icon('play')}<span class="scene-number">${String(s+1).padStart(2,'0')}</span><span>${esc(name)}</span></button>`).join('')}<button class="stop-all" data-action="stop-clips">${icon('stop')}Stop all clips</button><div class="master-mixer"><input class="volume-control master-volume" id="master-volume" aria-label="Master volume" type="range" min="0" max="1.2" step="0.005" value="${p.master}"><div class="master-main"><label>STEREO OUT</label><div class="meter-pair"><div class="meter-well"><i class="meter-fill" id="master-meter-l"></i></div><div class="meter-well"><i class="meter-fill" id="master-meter-r"></i></div></div><span id="master-value" class="master-value">${db(p.master)}</span></div></div>`;
  renderOverview();if(audio.meter)updateMeters(audio.meter);
}
function db(value){return value>.00001?`${(20*Math.log10(value)).toFixed(1)} dB`:'−∞ dB';}
function renderOverview(){const p=project(),total=Math.max(p.loopEnd,64);$('.overview-lanes').innerHTML=p.tracks.slice(0,6).map(t=>`<div class="overview-lane">${t.arrangement.map(a=>`<span style="background:${t.color};position:absolute;width:${a.length/total*100}%;left:${a.start/total*100}%"></span>`).join('')}</div>`).join('');}
function select(t,s=ui.scene){ui.track=clamp(t,0,project().tracks.length-1);ui.scene=clamp(s,0,project().scenes.length-1);ui.selectedNote=null;const c=clip();if(c?.notes.length){const min=Math.min(...c.notes.map(n=>n.pitch));ui.base=clamp(Math.floor(min/12)*12,0,104);}else ui.base=track().instrument==='drums'?36:48;renderSelection();renderDetail();ui.dirty=true;}
function renderSelection(){$$('.track-header').forEach(e=>e.classList.toggle('selected',+e.dataset.selectTrack===ui.track));$$('.clip').forEach(e=>e.classList.toggle('selected',+e.dataset.track===ui.track&&+e.dataset.scene===ui.scene));$$('.scene-launch').forEach(e=>e.classList.toggle('selected',+e.dataset.sceneLaunch===ui.scene));renderArrangementLabels();}
function renderDetail(){const t=track(),c=clip();if(!t)return;$('#detail-track').textContent=`${ui.track+1} — ${t.name}`;$('#clip-tab').classList.toggle('selected',ui.detail==='clip');$('#devices-tab').classList.toggle('selected',ui.detail==='devices');$('#clip-detail').classList.toggle('hidden',ui.detail!=='clip');$('#devices-detail').classList.toggle('hidden',ui.detail!=='devices');$('#duplicate-clip').disabled=!c;$('#delete-clip').disabled=!c;$('#clip-color').style.background=t.color;$('#clip-name').value=c?.name||'Empty slot';$('#clip-name').disabled=!c;$('#clip-type').textContent=c?(c.kind==='audio'?'AUDIO CLIP · PCM':'MIDI CLIP'):'NO CLIP SELECTED';$('#editor-empty').classList.toggle('hidden',!!c);const isAudio=c?.kind==='audio';$('#midi-properties').classList.toggle('hidden',isAudio);$('#sample-properties').classList.toggle('hidden',!isAudio);$('#pencil').classList.toggle('hidden',isAudio);$('#piano-keys').classList.toggle('hidden',isAudio);$('#pencil').classList.toggle('active',ui.draw);$('#clip-length').disabled=!c;
  if(c){if(![...$('#clip-length').options].some(o=>+o.value===c.length))$('#clip-length').add(new Option(`${(c.length/4).toFixed(2)} bars`,c.length));$('#clip-length').value=c.length;}
  if(isAudio){$('#trim-start').value=(c.trimStart*100).toFixed(1);$('#trim-end').value=(c.trimEnd*100).toFixed(1);$('#sample-reverse').classList.toggle('active',c.reverse);$('#sample-warp').classList.toggle('active',c.warp);const asset=audio.assets.get(c.sampleId);$('#editor-hint').textContent='Drag the start/end markers · Edits preserve the original sample · Double-click to launch';$('#editor-info').textContent=asset?`${(asset.frames/asset.sampleRate).toFixed(2)} s · ${(asset.sampleRate/1000).toFixed(1)} kHz · ${asset.channels.length} ch`:'Drop audio or choose a sample from the library';}
  else{$('#editor-hint').textContent='Double-click to add · Drag to move · Right edge to resize · Right-click to delete';$('#editor-info').textContent=`${c?.notes.length||0} notes · 1/${Math.round(4/ui.grid)} grid`;if(![...$('#octave').options].some(o=>+o.value===ui.base))$('#octave').add(new Option(`${noteName(ui.base)} — ${noteName(ui.base+23)}`,ui.base));$('#octave').value=ui.base;const n=c?.notes.find(n=>n.id===ui.selectedNote);$('#velocity').value=Math.round((n?.velocity??ui.velocity)*127);}
  renderPianoKeys();renderRuler();renderDevices();ui.dirty=true;
}
function renderPianoKeys(){$('#piano-keys').innerHTML=Array.from({length:24},(_,i)=>{const pitch=ui.base+23-i,black=[1,3,6,8,10].includes(pitch%12);return `<div class="piano-key ${black?'black':''} ${pitch%12===0?'root':''}" data-pitch="${pitch}" title="${noteName(pitch)}">${pitch%12===0?noteName(pitch):''}</div>`;}).join('');}
function renderRuler(){const c=clip();if(!c)return;let labels='';for(let b=0;b<c.length;b+=(c.length>16?4:1))labels+=`<span style="left:${b/c.length*100}%">${Math.floor(b/4)+1}${b%4?'.'+(b%4+1):''}</span>`;$('#editor-ruler').innerHTML=labels;}
function deviceRange(label,param,min,max,step,format){const v=track()[param]??0;return `<label>${label}<input data-param="${param}" type="range" min="${min}" max="${max}" step="${step}" value="${v}" aria-label="${label}"><output data-output="${param}">${format?format(v):Number(v).toFixed(2)}</output></label>`;}
function renderDevices(){const t=track(),samples=[...audio.assets.values()];$('#devices-detail').innerHTML=`<section class="device"><header class="device-header"><span><i class="device-power"></i>${t.type==='audio'?'Sample player':'Pulse instrument'}</span><small>01</small></header><div class="device-body">${t.type==='midi'?`<select id="instrument" aria-label="Instrument">${[['poly','Polyphonic synth'],['bass','Subtractive bass'],['pluck','Prism pluck'],['drums','Drum machine'],['sampler','PCM sampler']].map(([v,n])=>`<option value="${v}" ${t.instrument===v?'selected':''}>${n}</option>`).join('')}</select>${t.instrument==='sampler'?`<label>Sample<select id="sampler-asset"><option value="">Choose sample</option>${samples.map(a=>`<option value="${a.id}" ${a.id===t.sampleId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Root note<input type="number" id="root-note" min="0" max="127" value="${t.rootNote}"></label>`:`<label>Oscillator<select id="oscillator">${['saw','square','triangle','sine'].map(v=>`<option ${t.oscillator===v?'selected':''}>${v}</option>`).join('')}</select></label>`}${deviceRange('Attack','attack',.001,1,.001)}${deviceRange('Decay','decay',.01,2,.01)}${deviceRange('Sustain','sustain',0,1,.01)}${deviceRange('Release','release',.01,2,.01)}`:`<span class="device-label">NON-DESTRUCTIVE PCM</span>${clip()?`<label>Clip gain<input data-clip-param="gain" type="range" min="0" max="2" step=".01" value="${clip().gain}"></label><label>Fade in, ms<input data-clip-param="fadeIn" type="number" min="0" max="2000" value="${Math.round(clip().fadeIn*1000)}"></label><label>Fade out, ms<input data-clip-param="fadeOut" type="number" min="0" max="2000" value="${Math.round(clip().fadeOut*1000)}"></label>`:''}<button class="import-button" data-action="import">${icon('plus')}Load audio</button><div class="device-extra">Stereo playback · Trim / reverse<br>Tempo sync uses repitch<br>Original PCM is preserved</div>`}</div></section>
  <section class="device"><header class="device-header"><span><i class="device-power"></i>Color filter</span><small>02</small></header><div class="device-body">${deviceRange('Low pass','cutoff',60,18000,10,v=>v>=1000?(v/1000).toFixed(1)+'k':v)}${deviceRange('Resonance','resonance',.3,4,.01)}${deviceRange('Drive','drive',0,1,.01)}<div class="device-extra">Topology-preserving SVF<br>PolyBLEP saw / square oscillators</div></div></section>
  <section class="device"><header class="device-header"><span><i class="device-power"></i>Echo / sync</span><small>03</small></header><div class="device-body"><label>Time<select id="delay-time">${[[.25,'1/16'],[.5,'1/8'],[.75,'1/8 dotted'],[1,'1/4'],[1.5,'1/4 dotted'],[2,'1/2']].map(([v,n])=>`<option value="${v}" ${t.delayBeats===v?'selected':''}>${n}</option>`).join('')}</select></label>${deviceRange('Feedback','delayFeedback',0,.85,.01)}${deviceRange('Wet level','delayMix',0,.8,.01)}<div class="device-extra">Stereo cross-feedback delay<br>Synced to ${project().bpm} BPM</div></div></section>
  <section class="device"><header class="device-header"><span><i class="device-power"></i>Dynamics</span><small>04</small></header><div class="device-body">${deviceRange('Compression','compressor',0,1,.01)}<label>Lookahead<select id="lookahead">${[0,64,128,256,512,1024,2048].map(v=>`<option value="${v}" ${t.lookahead===v?'selected':''}>${v} samples</option>`).join('')}</select></label><div class="device-extra">Automatic internal delay compensation<br>All tracks align to the longest path.<br>No external plug-in hosting.</div></div></section>
  <section class="device"><header class="device-header"><span><i class="device-power"></i>Input / routing</span><small>05</small></header><div class="device-body"><label>Input monitor<input type="checkbox" id="input-monitor" ${t.monitor?'checked':''}></label><label>Record offset, ms<input id="record-offset" type="number" min="-500" max="500" value="${t.recordOffset||0}"></label><button id="device-mic" class="import-button">${icon('mic')}Record microphone</button><div class="device-extra">Microphone permission is requested only when recording. Use headphones with input monitoring.</div></div></section>`;
}
function renderArrangementLabels(){const p=project();$('#arrangement-labels').innerHTML=p.tracks.map((t,i)=>`<div class="arrangement-track-label ${i===ui.track?'selected':''}" style="height:${100/p.tracks.length}%;--track-color:${t.color}" data-select-track="${i}"><span>${i+1}</span>${esc(t.name)}</div>`).join('');let ruler='';for(let i=0;i<ui.bars;i++)ruler+=`<span style="left:${i/ui.bars*100}%">${i+1}</span>`;$('#arrangement-ruler').innerHTML=ruler;ui.dirty=true;}
function fitSession(){const panel=$('#session');if(!panel.offsetHeight)return;const header=$('.track-header')?.offsetHeight||36;const rows=project().scenes.length;panel.style.setProperty('--slot-height',Math.max(27,Math.min(48,(panel.clientHeight-header-27-149)/rows))+'px');}
function renderAll(){ui.track=clamp(ui.track,0,project().tracks.length-1);ui.scene=clamp(ui.scene,0,project().scenes.length-1);updateTitles();renderTracks();renderLibrary();renderSelection();renderDetail();applyView();}
function applyView(){const arrangement=project().mode==='arrangement';$('#session').classList.toggle('hidden',arrangement);$('#arrangement').classList.toggle('hidden',!arrangement);$('#session-tab').classList.toggle('selected',!arrangement);$('#arrangement-tab').classList.toggle('selected',arrangement);$('#session-tab').setAttribute('aria-selected',!arrangement);$('#arrangement-tab').setAttribute('aria-selected',arrangement);ui.dirty=true;}
function setView(view){commit(`Switched to ${view}`,p=>p.mode=view);}
function currentBeat(){const m=audio.meter;if(!m)return project().loopStart;const advance=m.playing&&audio.context?Math.max(0,audio.context.currentTime-m.frame/audio.context.sampleRate)*project().bpm/60:0;let b=m.beat+advance;if(project().mode==='arrangement'&&project().loop&&b>=project().loopEnd)b=project().loopStart+(b-project().loopEnd);return b;}
function clipPosition(){const m=audio.meter,c=clip();if(!c||!m?.playing||m.active[ui.track]!==ui.scene)return -1;const advance=audio.context?Math.max(0,audio.context.currentTime-m.frame/audio.context.sampleRate)*project().bpm/60:0;return ((m.positions?.[ui.track]??currentBeat())+advance)%c.length;}
function updateMeters(m){const percent=x=>clamp((20*Math.log10(Math.max(.000001,x))+60)/60*100,0,100);for(let i=0;i<project().tracks.length;i++){const l=$(`#meter-${i}-l`),r=$(`#meter-${i}-r`);if(l)l.style.height=percent(m.peaks[i*2])+'%';if(r)r.style.height=percent(m.peaks[i*2+1])+'%';}if($('#master-meter-l')){$('#master-meter-l').style.height=percent(m.masterL)+'%';$('#master-meter-r').style.height=percent(m.masterR)+'%';}
  $('#play').classList.toggle('playing',m.playing);$('#play').setAttribute('aria-label',m.playing?'Pause':'Play');$$('.clip').forEach(el=>{const t=+el.dataset.track,s=+el.dataset.scene,playing=m.playing&&m.active[t]===s,queued=m.pending[t]===s;el.classList.toggle('playing',playing);el.classList.toggle('queued',queued);const pos=el.querySelector('.clip-progress');pos.classList.toggle('hidden',!playing);if(playing){const c=project().tracks[t].clips[s];pos.style.left=(m.positions?.[t]??(m.beat%c.length))/c.length*100+'%';}});
}
const presets=[{name:'Glass keys',tag:'POLY',instrument:'poly',oscillator:'saw',cutoff:3300,attack:.022,release:.38,delayMix:.12},{name:'Sub circuit',tag:'BASS',instrument:'bass',oscillator:'square',cutoff:1400,attack:.004,release:.16,delayMix:0},{name:'Prism pluck',tag:'PLUCK',instrument:'pluck',oscillator:'triangle',cutoff:6000,attack:.003,release:.13,sustain:.12,delayMix:.22},{name:'Soft signal',tag:'SINE',instrument:'poly',oscillator:'sine',cutoff:10000,attack:.025,release:.5,delayMix:.15},{name:'Analog drift',tag:'POLY',instrument:'poly',oscillator:'saw',cutoff:2400,attack:.12,release:.8,delayMix:.1},{name:'Drum machine',tag:'DRUM',instrument:'drums',cutoff:14000,delayMix:0}];
function renderLibrary(){let items=[];const cat=ui.category,query=$('#browser-search').value.toLowerCase();if(cat==='Sounds'||cat==='Favorites'||cat==='Instruments'||cat==='Drums')items=presets.filter(p=>cat!=='Drums'||p.instrument==='drums').map(p=>({name:p.name,tag:p.tag,type:'preset',index:presets.indexOf(p),icon:p.instrument==='drums'?'drum':'key'}));
  else if(cat==='Audio Effects')items=[{name:'Color filter',tag:'SVF',type:'effect',index:'filter',icon:'knob'},{name:'Stereo echo',tag:'SYNC',type:'effect',index:'delay',icon:'knob'},{name:'Soft saturation',tag:'DRIVE',type:'effect',index:'drive',icon:'knob'},{name:'Lookahead dynamics',tag:'PDC',type:'effect',index:'compressor',icon:'knob'}];
  else items=[...audio.assets.values()].map(a=>({name:a.name,tag:'PCM',type:'sample',index:a.id,icon:'wave'}));
  items=items.filter(a=>a.name.toLowerCase().includes(query));$('#library-heading').textContent=cat.toUpperCase();$('#library-count').textContent=items.length;$('#library').innerHTML=items.length?items.map(i=>`<button class="library-item" data-library-type="${i.type}" data-library-id="${esc(i.index)}" title="Double-click to load ${esc(i.name)}">${icon(i.icon)}<span>${esc(i.name)}</span><span class="preset-tag">${i.tag}</span></button>`).join(''):'<div class="device-extra" style="padding:8px">No matching sounds.</div>';$$('[data-category]').forEach(b=>b.classList.toggle('selected',b.dataset.category===cat));}
function ensureClip(){if(!clip())commit('Create clip',p=>{p.tracks[ui.track].clips[ui.scene]=makeClip('New idea',8,track().type==='audio'?'audio':'midi');});return clip();}
function addTrack(type='midi'){if(project().tracks.length>=16){message('This engine is configured for up to 16 tracks.',true);return;}commit(`Add ${type} track`,p=>{const t=makeTrack(type==='audio'?'Audio '+(p.tracks.length+1):'MIDI '+(p.tracks.length+1),type==='audio'?'audio':'poly',COLORS[p.tracks.length%COLORS.length]);t.clips=Array(p.scenes.length).fill(null);p.tracks.push(t);ui.track=p.tracks.length-1;});select(ui.track);}
function addScene(){if(project().scenes.length>=32){message('This workspace supports up to 32 scenes.',true);return;}commit('Add scene',p=>{p.scenes.push(`Scene ${p.scenes.length+1}`);p.tracks.forEach(t=>t.clips.push(null));});}
function deleteClip(){const c=clip();if(!c)return;commit('Delete clip',()=>{track().arrangement=track().arrangement.filter(a=>a.clipId!==c.id);track().clips[ui.scene]=null;ui.selectedNote=null;});}
function duplicateClip(){const c=clip();if(!c)return;commit('Duplicate clip',p=>{let target=track().clips.findIndex((c,i)=>i>ui.scene&&!c);if(target<0){target=p.scenes.length;p.scenes.push(`Scene ${target+1}`);p.tracks.forEach(t=>t.clips.push(null));}const copy=clone(c);copy.id=uid();copy.name+=' copy';copy.notes.forEach(n=>n.id=uid());track().clips[target]=copy;ui.scene=target;});}
function showMenu(anchor,items){const menu=$('#menu'),r=anchor.getBoundingClientRect();menu.innerHTML=items.map(([name,action])=>name==='-'?'<hr>':`<button data-menu-action="${action}">${name}</button>`).join('');menu.style.left=Math.min(r.left,innerWidth-220)+'px';menu.style.top=r.bottom+4+'px';menu.classList.remove('hidden');}
function renameProject(){const name=prompt('Project name',project().name);if(name?.trim())commit('Rename project',p=>p.name=name.trim().slice(0,80));}
function saveFile(){download(serialize(project(),audio.assets),`${project().name.replace(/[^a-z0-9_-]/gi,'_')}.pulse`,'application/json');message('Project saved with its original audio samples.');scheduleSave();}
async function importAudio(files){for(const file of files){if(!file.size)continue;const asset=await audio.decode(file);audio.addSample(asset);if(track().instrument==='sampler'){commit('Load sampler audio',()=>track().sampleId=asset.id);continue;}
    if(track().type!=='audio')addTrack('audio');let target=ui.scene;if(track().clips[target]){target=track().clips.findIndex(c=>!c);if(target<0){addScene();target=project().scenes.length-1;}}
    commit(`Import ${file.name}`,p=>{const c=makeClip(file.name.replace(/\.[^.]+$/,''),8,'audio');c.sampleId=asset.id;c.length=Math.max(.25,Math.round(asset.frames/asset.sampleRate*p.bpm/60*4)/4);c.warp=false;track().clips[target]=c;ui.scene=target;});select(ui.track,target);message(`Imported ${file.name}: ${(asset.frames/asset.sampleRate).toFixed(2)} seconds.`);
  }renderLibrary();}
async function toggleRecord(forceMic=false){if(ui.record){if(ui.record.kind==='audio'){audio.stopRecording();}else{for(const [pitch] of ui.recordHeld)liveNote(pitch,0,false);message('MIDI recording stopped.');}ui.record=null;$('#record').classList.remove('recording');return;}
  await audio.enable();if(!forceMic){const armed=project().tracks.findIndex(t=>t.arm);if(armed>=0)select(armed);}if(forceMic&&track().type!=='audio')addTrack('audio');
  const t=track();if(t.type==='audio'){ui.record={kind:'audio',trackId:t.id,scene:ui.scene};try{await audio.startRecording();await audio.play();}catch(e){ui.record=null;throw e;}}
  else{const c=ensureClip();ui.record={kind:'midi',trackId:t.id,clipId:c.id,scene:ui.scene};await audio.launch(ui.track,ui.scene);}
  $('#record').classList.add('recording');message(ui.record.kind==='audio'?'Recording raw microphone PCM. Press Record to finish.':'MIDI overdub armed. Play the computer keyboard or a MIDI input.');
}
function liveNote(pitch,velocity,on){if(pitch<0||pitch>127)return;let index=ui.track;const armed=project().tracks.findIndex(t=>t.arm&&t.type==='midi');if(armed>=0)index=armed;if(ui.record?.kind==='midi'){const recordingTrack=project().tracks.findIndex(t=>t.id===ui.record.trackId);if(recordingTrack>=0)index=recordingTrack;}if(on)liveRoutes.set(pitch,index);else{index=liveRoutes.get(pitch)??index;liveRoutes.delete(pitch);}audio.note(index,pitch,velocity,on);
  if(ui.record?.kind==='midi'){
    const ri=project().tracks.findIndex(t=>t.id===ui.record.trackId),rt=project().tracks[ri],rc=rt?.clips.find(c=>c?.id===ui.record.clipId);if(!rc)return;
    if(on){if(audio.meter?.pending[ri]>=0)return;const absolute=currentBeat(),advance=audio.context&&audio.meter?Math.max(0,audio.context.currentTime-audio.meter.frame/audio.context.sampleRate)*project().bpm/60:0,local=((audio.meter?.positions?.[ri]??absolute)+advance)%rc.length;ui.recordHeld.set(pitch,{start:Math.max(0,local),absolute,velocity});}
    else{const held=ui.recordHeld.get(pitch);if(held){ui.recordHeld.delete(pitch);const start=Math.round(held.start/ui.grid)*ui.grid%rc.length,duration=Math.max(ui.grid,Math.round((currentBeat()-held.absolute)/ui.grid)*ui.grid);commit('Record MIDI note',()=>rc.notes.push({id:uid(),pitch,start,duration:Math.min(duration,rc.length),velocity:held.velocity}));}}
  }
}
