function drawEditor(){editor.begin();const s=editor,g=editorGeometry(),c=clip(),t=track();s.background='#222a23';if(!c){s.end();return;}s.rect(0,0,s.width,22,'#3d4837');
  if(c.kind==='audio'){
    const a=audio.assets.get(c.sampleId);s.rect(g.left,22,g.width,g.height+16,'#252f23');s.rect(g.left,22+(g.height+16)/2,g.width,1,'#556749');if(a)waves.draw(s,a,g.left,25,g.width,g.height+10,t.color,0,1,false);
    for(let b=0;b<=c.length;b+=Math.max(1,c.length/32)){const x=g.left+b/c.length*g.width;s.rect(x,22,1,g.height+15,'#677756',.3);}
    const start=g.left+c.trimStart*g.width,end=g.left+c.trimEnd*g.width;s.rect(g.left,22,start-g.left,g.height+15,'#121d13',.75);s.rect(end,22,g.left+g.width-end,g.height+15,'#121d13',.75);s.rect(start,22,2,g.height+15,'#f3c597');s.rect(end-2,22,2,g.height+15,'#f3c597');s.rect(start,22,8,8,'#f3c597');s.rect(end-8,22,8,8,'#f3c597');const position=clipPosition();if(position>=0)s.rect(c.reverse?end-(position/c.length)*(end-start):start+(position/c.length)*(end-start),22,1,g.height+15,'#f8e9c1');
  }else{
    for(let i=0;i<24;i++){const pitch=ui.base+23-i,black=[1,3,6,8,10].includes(pitch%12);s.rect(g.left,g.top+i*g.row,g.width,g.row,black?'#252f24':'#2e392a');s.rect(g.left,g.top+(i+1)*g.row-1,g.width,1,'#1c271d');}
    for(let beat=0;beat<=c.length;beat+=ui.grid){const x=g.left+beat/c.length*g.width,bar=Math.abs(beat%4)<.001,whole=Math.abs(beat%1)<.001;s.rect(x,22,bar?1.2:1,g.height+15,bar?'#697754':whole?'#4c5d40':'#36492f');}
    s.rect(g.left,s.height-35,g.width,15,'#303e29');
    for(const n of c.notes){if(n.pitch<ui.base||n.pitch>=ui.base+24)continue;const x=g.left+n.start/c.length*g.width,y=g.top+(ui.base+23-n.pitch)*g.row+1,w=Math.max(3,Math.min(n.duration,c.length-n.start)/c.length*g.width-1),selected=n.id===ui.selectedNote;s.rect(x,y,w,Math.max(2,g.row-2),selected?'#f1d1a0':t.color,.62+n.velocity*.38);s.rect(x,y,2,Math.max(2,g.row-2),'#f2f0d2',.3);if(selected){s.rect(x,y,w,1,'#fff6d1');s.rect(x,y+g.row-3,w,1,'#fff6d1');}s.rect(x,s.height-22-n.velocity*11,Math.max(2,Math.min(5,w)),n.velocity*11,t.color);}
    const pos=clipPosition();if(pos>=0)s.rect(g.left+pos/c.length*g.width,22,1,g.height+15,'#f5ebc5');
  }s.end();
}
function arrangementGeometry(){return {left:126,top:25,width:Math.max(1,arranger.width-126),row:Math.max(1,(arranger.height-25)/project().tracks.length),beats:ui.bars*4};}
function drawArrangement(){arranger.begin();const s=arranger,g=arrangementGeometry(),p=project();s.background='#222b24';for(let ti=0;ti<p.tracks.length;ti++){const t=p.tracks[ti],y=g.top+ti*g.row;s.rect(g.left,y,g.width,g.row,ti%2?'#283327':'#2c372b');s.rect(g.left,y+g.row-1,g.width,1,'#182519');}
  s.rect(0,0,s.width,25,'#3a4835');for(let b=0;b<=g.beats;b++){const x=g.left+b/g.beats*g.width;s.rect(x,25,1,s.height-25,b%4===0?'#5d704c':'#364b31');}
  let labels='';for(let ti=0;ti<p.tracks.length;ti++){const t=p.tracks[ti],y=g.top+ti*g.row;for(const a of t.arrangement){const c=t.clips.find(c=>c?.id===a.clipId);if(!c)continue;const x=g.left+a.start/g.beats*g.width,w=a.length/g.beats*g.width;if(x>=s.width)continue;const visibleW=Math.min(w,s.width-x);s.rect(x+1,y+3,visibleW-2,g.row-6,t.color,.33);s.rect(x+1,y+3,visibleW-2,14,t.color,.36);s.rect(x+1,y+3,2,g.row-6,t.color);if(a.id===ui.selectedInstance){s.rect(x+1,y+3,visibleW-2,1,'#f2e6b7');s.rect(x+1,y+g.row-4,visibleW-2,1,'#f2e6b7');s.rect(x+visibleW-2,y+3,1,g.row-6,'#f2e6b7');}
      if(c.kind==='audio'){const asset=audio.assets.get(c.sampleId);if(asset)waves.draw(s,asset,x+3,y+18,Math.max(1,visibleW-6),Math.max(8,g.row-25),t.color,c.trimStart,c.trimEnd,c.reverse,.7);}
      else for(let repeat=0;repeat<a.length;repeat+=c.length){for(const n of c.notes){const start=repeat+n.start;if(start>=a.length)continue;const nx=x+start/g.beats*g.width,nw=Math.max(2,Math.min(n.duration,a.length-start)/g.beats*g.width),ny=y+19+(1-(n.pitch%36)/36)*Math.max(4,g.row-27);s.rect(nx+1,ny,nw,2,t.color,.8);}}
      labels+=`<span class="arrangement-clip-label" style="left:${x+4}px;top:${y+3}px;width:${Math.max(1,visibleW-10)}px">${esc(c.name)}</span>`;
    }
    if(ui.automation&&ti===ui.track){let prevX=g.left,prevY=y+g.row*(1-(t.automation[0]?.value??1));s.rect(g.left,y,g.width,g.row,'#132318',.35);for(const a of t.automation){const x=g.left+a.beat/g.beats*g.width,ay=y+5+(1-a.value)*(g.row-10);s.line(prevX,prevY,x,ay,'#edd099',1.5);s.rect(x-3,ay-3,6,6,'#f0d39f');prevX=x;prevY=ay;}s.line(prevX,prevY,s.width,prevY,'#edd099',1.5);}
  }
  const end=g.left+p.loopEnd/g.beats*g.width;s.rect(g.left+p.loopStart/g.beats*g.width,0,(p.loopEnd-p.loopStart)/g.beats*g.width,3,'#bcc88f');s.rect(end-1,0,1,25,'#bcc88f');const beat=currentBeat();s.rect(g.left+beat/g.beats*g.width,0,1,s.height,'#f5e8b7');s.end();if($('#arrangement-clip-labels').innerHTML!==labels)$('#arrangement-clip-labels').innerHTML=labels;
}
function noteHit(x,y){const c=clip(),g=editorGeometry();if(!c||c.kind!=='midi')return null;for(let i=c.notes.length-1;i>=0;i--){const n=c.notes[i],nx=g.left+n.start/c.length*g.width,ny=g.top+(ui.base+23-n.pitch)*g.row;if(x>=nx&&x<=nx+Math.max(4,n.duration/c.length*g.width)&&y>=ny&&y<ny+g.row)return n;}return null;}
function editorPoint(e){const r=editor.canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};}
function addNoteAt(x,y){const c=clip(),g=editorGeometry();if(!c||c.kind!=='midi'||x<g.left||y<g.top||y>=g.top+g.height)return;const start=clamp(Math.floor((x-g.left)/g.width*c.length/ui.grid)*ui.grid,0,c.length-ui.grid),pitch=clamp(ui.base+23-Math.floor((y-g.top)/g.row),0,127);commit('Draw MIDI note',()=>{const note={id:uid(),pitch,start,duration:ui.grid,velocity:ui.velocity};c.notes.push(note);ui.selectedNote=note.id;});if(audio.context){audio.note(ui.track,pitch,ui.velocity,true);const ti=ui.track;setTimeout(()=>audio.note(ti,pitch,0,false),120);}}
$('#editor-wrap').addEventListener('pointerdown',e=>{if(e.target!==editor.canvas||e.button!==0||!clip())return;const {x,y}=editorPoint(e),c=clip(),g=editorGeometry();if(x<g.left||y<22)return;editor.canvas.setPointerCapture(e.pointerId);
  if(c.kind==='audio'){const u=clamp((x-g.left)/g.width,0,1),which=Math.abs(u-c.trimStart)<Math.abs(u-c.trimEnd)?'trimStart':'trimEnd';ui.gesture={type:'trim',which,before:clone(project()),clip:c};}
  else {const n=noteHit(x,y);if(n){ui.selectedNote=n.id;const right=g.left+(n.start+n.duration)/c.length*g.width;ui.gesture={type:x>right-7?'resize-note':'move-note',before:clone(project()),note:n,startX:x,startY:y,original:{...n}};renderDetail();}
    else if(ui.draw)addNoteAt(x,y);else{ui.selectedNote=null;renderDetail();}}
  ui.dirty=true;
});
$('#editor-wrap').addEventListener('pointermove',e=>{const drag=ui.gesture;if(!drag||!['trim','resize-note','move-note'].includes(drag.type))return;const {x,y}=editorPoint(e),g=editorGeometry(),c=clip();if(drag.type==='trim'){const u=clamp((x-g.left)/g.width,0,1);c[drag.which]=drag.which==='trimStart'?Math.min(u,c.trimEnd-.001):Math.max(u,c.trimStart+.001);}
  else{const n=drag.note,original=drag.original,delta=Math.round((x-drag.startX)/g.width*c.length/ui.grid)*ui.grid;if(drag.type==='resize-note')n.duration=clamp(original.duration+delta,Math.min(ui.grid,c.length),c.length-n.start);else{n.start=clamp(original.start+delta,0,Math.max(0,c.length-ui.grid));n.pitch=clamp(original.pitch-Math.round((y-drag.startY)/g.row),0,127);}}ui.dirty=true;});
function finishGesture(){const gesture=ui.gesture;if(!gesture)return;ui.gesture=null;const changed=JSON.stringify(gesture.before)!==JSON.stringify(project());if(changed){history.past.push({label:gesture.type,state:gesture.before});if(history.past.length>80)history.past.shift();history.future=[];history.onChange(project(),'Edit '+gesture.type);}else ui.dirty=true;}
window.addEventListener('pointerup',finishGesture);window.addEventListener('pointercancel',()=>{if(ui.gesture){history.project=ui.gesture.before;ui.gesture=null;audio.setProject(project());renderAll();}});
$('#editor-wrap').addEventListener('dblclick',e=>{if(e.target!==editor.canvas)return;const{x,y}=editorPoint(e);if(clip()?.kind==='audio')safe(()=>audio.launch(ui.track,ui.scene));else if(!noteHit(x,y)&&!ui.draw)addNoteAt(x,y);});
$('#editor-wrap').addEventListener('contextmenu',e=>{if(e.target!==editor.canvas)return;e.preventDefault();const{x,y}=editorPoint(e),n=noteHit(x,y);if(n)commit('Delete MIDI note',()=>{clip().notes=clip().notes.filter(a=>a.id!==n.id);ui.selectedNote=null;});});
$('#editor-wrap').addEventListener('wheel',e=>{if(clip()?.kind!=='midi')return;e.preventDefault();ui.base=clamp(ui.base+(e.deltaY>0?-1:1),0,104);renderDetail();},{passive:false});
function arrangementPoint(e){const r=arranger.canvas.getBoundingClientRect(),g=arrangementGeometry(),x=e.clientX-r.left,y=e.clientY-r.top;return {x,y,beat:clamp((x-g.left)/g.width*g.beats,0,g.beats),ti:clamp(Math.floor((y-g.top)/g.row),0,project().tracks.length-1)};}
function instanceAt(point){return project().tracks[point.ti].arrangement.slice().reverse().find(a=>point.beat>=a.start&&point.beat<a.start+a.length);}
$('#arrangement-body').addEventListener('pointerdown',e=>{if(e.target!==arranger.canvas||e.button!==0)return;const p=arrangementPoint(e),g=arrangementGeometry();if(p.x<g.left)return;if(p.y<g.top){audio.send({type:'seek',beat:Math.floor(p.beat/ui.grid)*ui.grid});ui.dirty=true;return;}
  select(p.ti);arranger.canvas.setPointerCapture(e.pointerId);const t=track();if(ui.automation){const before=clone(project()),beat=Math.round(p.beat/ui.grid)*ui.grid,value=clamp(1-(p.y-g.top-p.ti*g.row-5)/(g.row-10),0,1);let a=t.automation.find(a=>Math.abs(a.beat-beat)<ui.grid/2);if(a)a.value=value;else{a={beat,value};t.automation.push(a);t.automation.sort((a,b)=>a.beat-b.beat);}ui.gesture={type:'automation',before,point:a,track:t};ui.dirty=true;return;}
  const a=instanceAt(p);if(a){ui.selectedInstance=a.id;ui.scene=t.clips.findIndex(c=>c?.id===a.clipId);renderDetail();const right=g.left+(a.start+a.length)/g.beats*g.width;ui.gesture={type:p.x>right-8?'resize-instance':'move-instance',before:clone(project()),instance:a,startBeat:p.beat,original:{...a}};}else ui.selectedInstance=null;ui.dirty=true;
});
$('#arrangement-body').addEventListener('pointermove',e=>{const d=ui.gesture;if(!d)return;const p=arrangementPoint(e),g=arrangementGeometry();if(d.type==='automation'){d.point.beat=Math.round(p.beat/ui.grid)*ui.grid;d.point.value=clamp(1-(p.y-g.top-ui.track*g.row-5)/(g.row-10),0,1);d.track.automation.sort((a,b)=>a.beat-b.beat);}
  else if(d.type==='move-instance')d.instance.start=Math.max(0,d.original.start+Math.round((p.beat-d.startBeat)/ui.grid)*ui.grid);else if(d.type==='resize-instance')d.instance.length=Math.max(ui.grid,d.original.length+Math.round((p.beat-d.startBeat)/ui.grid)*ui.grid);else return;ui.dirty=true;
});
$('#arrangement-body').addEventListener('dblclick',e=>{if(e.target!==arranger.canvas||ui.automation)return;const p=arrangementPoint(e);if(instanceAt(p)||p.y<25)return;select(p.ti);const c=ensureClip();commit('Insert arrangement clip',()=>{const a={id:uid(),clipId:c.id,start:Math.floor(p.beat/4)*4,length:c.length,offset:0};track().arrangement.push(a);ui.selectedInstance=a.id;});});
$('#arrangement-body').addEventListener('contextmenu',e=>{e.preventDefault();const p=arrangementPoint(e);if(ui.automation){const t=project().tracks[p.ti],nearest=t.automation.reduce((a,b)=>!a||Math.abs(b.beat-p.beat)<Math.abs(a.beat-p.beat)?b:a,null);if(nearest)commit('Delete automation point',()=>t.automation=t.automation.filter(a=>a!==nearest));}else{const a=instanceAt(p);if(a)commit('Delete arrangement instance',()=>project().tracks[p.ti].arrangement=project().tracks[p.ti].arrangement.filter(i=>i.id!==a.id));}});
$('#arrangement-body').addEventListener('drop',e=>{const data=e.dataTransfer.getData('application/x-pulsegrid-clip');if(!data)return;e.preventDefault();e.stopPropagation();const source=JSON.parse(data),p=arrangementPoint(e),original=project().tracks[source.track].clips[source.scene];if(!original)return;commit('Place Session clip in arrangement',model=>{const t=model.tracks[p.ti];let c=t.clips.find(c=>c?.id===original.id);if(!c){c=clone(original);c.id=uid();c.notes.forEach(n=>n.id=uid());const empty=t.clips.findIndex(c=>!c);if(empty>=0)t.clips[empty]=c;else{model.scenes.push('Imported scene');model.tracks.forEach(t=>t.clips.push(null));t.clips[t.clips.length-1]=c;}}t.arrangement.push({id:uid(),clipId:c.id,start:Math.floor(p.beat/4)*4,length:c.length,offset:0});});});
$('#arrangement-tab').addEventListener('dragenter',()=>{if(project().mode!=='arrangement')setView('arrangement');});
// Render only dirty surfaces while stopped; requestAnimationFrame never schedules sound.
let lastFrame=0;function frame(time){requestAnimationFrame(frame);fitSession();if(time-lastFrame<15)return;lastFrame=time;const beat=currentBeat(),playing=audio.meter?.playing;const bar=Math.floor(beat/4)+1,b=Math.floor(beat%4)+1,s=Math.floor((beat%1)*4)+1;$('#position').innerHTML=`${bar} <span>.</span> ${b} <span>.</span> ${s}`;$('#overview-position').style.left=beat/Math.max(64,project().loopEnd)*100+'%';if(ui.dirty||playing){if(ui.detail==='clip'&&!$('#detail').classList.contains('collapsed'))drawEditor();if(project().mode==='arrangement')drawArrangement();ui.dirty=false;}}
new ResizeObserver(()=>ui.dirty=true).observe($('#detail'));new ResizeObserver(()=>ui.dirty=true).observe($('#arrangement-body'));window.addEventListener('resize',()=>{renderArrangementLabels();ui.dirty=true;});
for(const asset of factorySamples())audio.addSample(asset);
try{const saved=await restore();if(saved?.project){validateProject(saved.project);history.project=saved.project;audio.clearSamples();for(const asset of saved.assets)audio.addSample(asset);$('#save-status').textContent='Restored locally';}}catch(e){console.warn('Local project restore skipped:',e.message);}
audio.setProject(project());renderAll();requestAnimationFrame(frame);
window.pulsegrid=Object.freeze({audio,history,ui,surfaces:{editor,arranger},get project(){return project();},get assets(){return audio.assets;},save:saveFile,serialize:()=>serialize(project(),audio.assets)});
